-- 1. BẢNG DANH MỤC DỊCH VỤ (categories)
DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `name_vi` VARCHAR(255) NOT NULL,
  `icon` VARCHAR(32) NOT NULL,
  `description` TEXT,
