) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `categories` (`id`, `name`, `name_vi`, `icon`, `description`, `count`) VALUES ('CAT_ATTRACTION', 'Attractions & Sightseeing', 'Điểm tham quan & Danh thắng', '🏛️', '15 di tích lịch sử, cảnh quan thiên nhiên và thắng cảnh nổi tiếng tại xứ hoa đào.', 0);
INSERT INTO `categories` (`id`, `name`, `name_vi`, `icon`, `description`, `count`) VALUES ('CAT_CAFE', 'Cafes & Photo Spots', 'Quán Cafe view đẹp & Sống ảo', '☕', '12 tọa độ cafe săn mây, ngắm thung lũng đèn đêm và acoustic lãng mạn.', 0);
INSERT INTO `categories` (`id`, `name`, `name_vi`, `icon`, `description`, `count`) VALUES ('CAT_FOOD', 'Dining & Local Cuisine', 'Quán ăn & Đặc sản nức tiếng', '🍲', '13 tinh hoa ẩm thực phố núi từ lẩu nghi ngút khói đến các món ăn vặt đường phố trứ danh.', 0);
