-- 5. BẢNG ĐÁNH GIÁ & NHẬN XÉT (reviews)
DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `service_id` VARCHAR(100) NOT NULL,
  `service_name` VARCHAR(255),
  `user_id` VARCHAR(64) NOT NULL,
  `user_name` VARCHAR(255),
  `user_avatar` TEXT,
  `rating` INT DEFAULT 5,
  `comment` TEXT,
  `images_json` JSON,
  `created_at` VARCHAR(64),
  `status` ENUM('approved', 'hidden') DEFAULT 'approved'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `reviews` VALUES ('REV_1794233210914', 'SRV_46_HOTEL_COLLINE', 'Hôtel Colline', 'USR_TUANANH', 'Tuấn Anh (Auth & Người Dùng)', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80', 5, '1213445', '[]', '2026-11-09T14:06:50.914Z', 'approved');
INSERT INTO `reviews` VALUES ('REV_1', 'SRV_16_TUI_MO_TO', 'Tiệm Cà Phê Túi Mơ To', 'USR_TUANANH', 'Tuấn Anh', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80', 5, 'Vườn cúc họa mi trắng nở rộ ngút ngàn. Không gian nhà gỗ vintage ấm cúng và view nhìn xuống thung lũng nhà lồng lung linh khi lên đèn!', '[]', '2026-02-14T10:15:00Z', 'approved');
INSERT INTO `reviews` VALUES ('REV_2', 'SRV_28_LAU_GA_TAO_NGO', 'Lẩu Gà Lá É Tao Ngộ', 'USR_BINH', 'Bình', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80', 5, 'Thịt gà đồi rất chắc, nước dùng thơm lừng vị lá é và ớt hiểm the the giải cảm cực tốt trong tiết trời se lạnh.', '[]', '2026-02-20T19:30:00Z', 'approved');
INSERT INTO `reviews` VALUES ('REV_3', 'SRV_12_DOI_CHE_CAU_DAT', 'Đồi chè Cầu Đất', 'USR_QUANG', 'Quang', 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=200&q=80', 5, 'Dậy sớm từ 4h30 chạy lên cầu gỗ đón biển mây bồng bềnh và ngắm cánh quạt gió khổng lồ dưới ánh bình minh 5h30 quá mãn nhãn!', '[]', '2026-02-25T06:00:00Z', 'approved');
INSERT INTO `reviews` VALUES ('REV_4', 'SRV_07_HO_TUYEN_LAM', 'Hồ Tuyền Lâm', 'USR_MINHANH', 'Minh Anh', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=200&q=80', 5, 'Chèo thuyền SUP sáng sớm trên mặt hồ phẳng lặng như gương, hít thở không khí rừng thông trong lành thật sảng khoái.', '[]', '2026-03-01T08:00:00Z', 'approved');
INSERT INTO `reviews` VALUES ('REV_5', 'SRV_29_LAU_BO_BA_TOA', 'Lẩu Bò Ba Toa Quán Gỗ', 'USR_TUANANH', 'Tuấn Anh', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80', 5, 'Nồi lẩu bò ngập tràn bắp bò, gân và đuôi bò mềm rụm. Nước dùng hầm từ xương ống đậm đà đúng chất quán gỗ Ba Toa.', '[]', '2026-03-02T12:00:00Z', 'approved');
INSERT INTO `reviews` VALUES ('REV_6', 'SRV_46_HOTEL_COLLINE', 'Hôtel Colline', 'USR_ADMIN', 'Việt (Admin)', '', 5, 'Vị trí đắc địa ngay Dalat Center, chỉ cần đi bộ 3 phút là xuống ngay chợ đêm. Phòng ốc thiết kế hiện đại sang trọng.', '[]', '2026-03-03T14:00:00Z', 'approved');

-- 6. BẢNG ĐỊA ĐIỂM YÊU THÍCH (favorites)
DROP TABLE IF EXISTS `favorites`;
CREATE TABLE `favorites` (
  `service_id` VARCHAR(100) NOT NULL PRIMARY KEY,
  `created_at` VARCHAR(64)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 7. BẢNG THÔNG BÁO HỆ THỐNG (notifications)
DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `title` VARCHAR(255),
  `title_vi` VARCHAR(255),
  `message` TEXT,
  `message_vi` TEXT,
  `type` VARCHAR(64),
  `timestamp` VARCHAR(64),
  `is_read` TINYINT(1) DEFAULT 0,
  `link_service_id` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

