INSERT INTO `notifications` VALUES ('NOTIF_3', 'Đêm se lạnh 14°C: Thưởng thức Lẩu Gà Lá É & Bò Ba Toa', 'Đêm se lạnh 14°C: Thưởng thức Lẩu Gà Lá É & Bò Ba Toa', 'Thời tiết Đà Lạt tối nay rất lý tưởng cho các món lẩu nóng hổi bên bạn bè và gia đình.', 'Thời tiết Đà Lạt tối nay rất lý tưởng cho các món lẩu nóng hổi bên bạn bè và gia đình.', 'promo', '2026-03-05T18:00:00Z', 1, 'SRV_28_LAU_GA_TAO_NGO');